<?php
namespace Modules\Glitter\NotificationHub\Http\Controllers\Admin;
use App\Helpers\ResponseHelper;use App\Http\Controllers\Api\Base\AdminBaseController;use Illuminate\Http\JsonResponse;use Modules\Glitter\NotificationHub\DTO\Admin\ManualRetryData;use Modules\Glitter\NotificationHub\DTO\Admin\NotificationPlanSearchData;use Modules\Glitter\NotificationHub\Http\Requests\Admin\CancelNotificationPlanRequest;use Modules\Glitter\NotificationHub\Http\Requests\Admin\ListNotificationPlansRequest;use Modules\Glitter\NotificationHub\Http\Requests\Admin\RetryNotificationPlanRequest;use Modules\Glitter\NotificationHub\Http\Resources\Admin\NotificationPlanCollection;use Modules\Glitter\NotificationHub\Http\Resources\Admin\NotificationPlanResource;use Modules\Glitter\NotificationHub\Services\Admin\NotificationHubAdminService;
class NotificationPlanController extends AdminBaseController { public function __construct(private readonly NotificationHubAdminService $service){} public function index(ListNotificationPlansRequest $r):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.plans_retrieved',new NotificationPlanCollection($this->service->listPlans(NotificationPlanSearchData::fromArray($r->validated()))));} public function show(string $plan):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.plan_retrieved',new NotificationPlanResource($this->service->getPlan($plan)));} public function cancel(CancelNotificationPlanRequest $r,string $plan):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.plan_cancelled',$this->service->cancelPlan($plan,$r->validated('reason'),$r->user()?->id));} public function retry(RetryNotificationPlanRequest $r,string $plan):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.plan_retry_created',$this->service->retryPlan($plan,ManualRetryData::fromArray($r->validated(),$r->user()?->id))->toArray(),201);} }
